int digi()
{
  // Macro created 20/09/2006 by S.Spataro
  // It loads a simulation file and digitize hits

  // Verbosity level (0=quiet, 1=event level, 2=track level, 3=debug)
  Int_t iVerbose = 0; // just forget about it, for the moment

  // Input file (MC events)
  TString simFile = "sim.root";
  PndFileNameCreator creator(simFile.Data());
  TString digiFile = creator.GetDigiFileName();
  TString parFile = creator.GetParFileName();

  // Digitisation file (ascii)
  TString digiParFile = "all.par";

  // Output file

  // -----   Timer   --------------------------------------------------------
  TStopwatch timer;

  // -----   Reconstruction run   -------------------------------------------
  FairRunAna *fRun = new FairRunAna();
  fRun->SetInputFile(simFile);
  fRun->SetOutputFile(digiFile);
  fRun->SetGenerateRunInfo(kFALSE);

  // -----  Parameter database   --------------------------------------------
  TString allDigiFile = gSystem->Getenv("VMCWORKDIR");
  allDigiFile += "/macro/params/";
  allDigiFile += digiParFile;

  FairRuntimeDb *rtdb = fRun->GetRuntimeDb();
  FairParRootFileIo *parInput1 = new FairParRootFileIo();
  parInput1->open(parFile.Data());

  FairParAsciiFileIo *parIo1 = new FairParAsciiFileIo();
  parIo1->open(allDigiFile.Data(), "in");

  rtdb->setFirstInput(parInput1);
  rtdb->setSecondInput(parIo1);

  // -----   STT digi producers   ---------------------------------
  // PndSttHitProducerRealFast* sttHitProducer = new PndSttHitProducerRealFast();
  // fRun->AddTask(sttHitProducer);

  // -----   MDV digi producers   ---------------------------------
  PndMvdDigiTask *mvddigi = new PndMvdDigiTask();
  mvddigi->SetVerbose(iVerbose);
  fRun->AddTask(mvddigi);

  // -----   EMC digi producers   ---------------------------------
  PndEmcHitsToWaveform *emcHitsToWaveform = new PndEmcHitsToWaveform(iVerbose);
  PndEmcWaveformToDigi *emcWaveformToDigi = new PndEmcWaveformToDigi(iVerbose);
  emcHitsToWaveform->SetStorageOfData(kFALSE);
  // emcWaveformToDigi->SetStorageOfData(kFALSE);
  fRun->AddTask(emcHitsToWaveform); // full digitization
  fRun->AddTask(emcWaveformToDigi); // full digitization

  // -----   SciT hit producers   ---------------------------
  // PndSciTHitProducerIdeal* tofhit = new PndSciTHitProducerIdeal();
  // tofhit->SetVerbose(iVerbose);
  // fRun->AddTask(tofhit);

  // -----   MDT hit producers   ---------------------------------
  // PndMdtHitProducerIdeal* mdtHitProd = new PndMdtHitProducerIdeal();
  // mdtHitProd->SetPositionSmearing(.3); // position smearing [cm]
  // fRun->AddTask(mdtHitProd);

  // -----   DRC hit producers   ---------------------------------
  // PndDrcHitProducerReal* drchit = new PndDrcHitProducerReal();
  // drchit->SetVerbose(iVerbose);
  // fRun->AddTask(drchit);

  // -----   GEM hit producers   ---------------------------------
  PndGemDigitize *gemDigitize = new PndGemDigitize("GEM Digitizer", iVerbose);
  fRun->AddTask(gemDigitize);
  // -----   FTS hit producers   ---------------------------------
  // PndFtsHitProducerRealFast* ftsHitProducer = new PndFtsHitProducerRealFast();
  // fRun->AddTask(ftsHitProducer);

  // -----   Ftof hit producers   ---------------------------
  // PndFtofHitProducerIdeal* ftofhit = new PndFtofHitProducerIdeal();
  // ftofhit->SetVerbose(iVerbose);
  // fRun->AddTask(ftofhit);

  // -----   Intialise and run   --------------------------------------------
  fRun->Init();

  timer.Start();
  fRun->Run();

sim(Int_t nEvents = 100, TString SimEngine = "TGeant3", Float_t mom = 6.231552)
{
  //-----User Settings:-----------------------------------------------
  TString OutputFile = "sim.root";
  PndFileNameCreator creator(OutputFile.Data());
  TString ParOutputfile = creator.GetParFileName();
  TString MediaFile = "media_pnd.geo";
  gDebug = 0;
  TString digiParFile = "all.par"; // The emc run the hit producer directly
  // choose your event generator
  Bool_t UseEvtGenDirect = kFALSE;
  Bool_t UseDpm = kTRUE;
  Bool_t UseFtf = kFALSE;

  Double_t BeamMomentum = 0.; // beam momentum ONLY for the scaling of the dipole field.
  BeamMomentum = mom;         // for DPM/EvtGen BeamMomentum is always = mom
  //------------------------------------------------------------------
  TLorentzVector fIni(0, 0, mom, sqrt(mom * mom + 9.3827203e-01 * 9.3827203e-01) + 9.3827203e-01);
  TDatabasePDG::Instance()->AddParticle("pbarpSystem", "pbarpSystem", fIni.M(), kFALSE, 0.1, 0, "", 88888);
  //------------------------------------------------------------------
  TStopwatch timer;
  timer.Start();
  gRandom->SetSeed();

  // Create the Simulation run manager--------------------------------
  FairRunSim *fRun = new FairRunSim();
  fRun->SetName(SimEngine.Data());
  fRun->SetOutputFile(OutputFile.Data());
  fRun->SetGenerateRunInfo(kFALSE);
  fRun->SetBeamMom(BeamMomentum);
  fRun->SetMaterials(MediaFile.Data());
  FairRuntimeDb *rtdb = fRun->GetRuntimeDb();

  // Set the parameters
  //-------------------------------
  TString allDigiFile = gSystem->Getenv("VMCWORKDIR");
  allDigiFile += "/macro/params/";
  allDigiFile += digiParFile;

  //-------Set the parameter output --------------------
  FairParAsciiFileIo *parIo1 = new FairParAsciiFileIo();
  parIo1->open(allDigiFile.Data(), "in");
  rtdb->setFirstInput(parIo1);

  //---------------------Set Parameter output      ----------
  Bool_t kParameterMerged = kTRUE;
  FairParRootFileIo *output = new FairParRootFileIo(kParameterMerged);
  output->open(ParOutputfile.Data());
  rtdb->setOutput(output);

  // Create and add detectors

  //-------------------------  CAVE      -----------------

  FairModule *Cave = new PndCave("CAVE");
  Cave->SetGeometryFileName("pndcave.geo");
  fRun->AddModule(Cave);
  //-------------------------  Magnet   -----------------
  FairModule *Dipole = new PndMagnet("MAGNET");
  Dipole->SetGeometryFileName("dipole.geo");
  fRun->AddModule(Dipole);
  //-------------------------  Pipe     -----------------
  FairModule *Pipe = new PndPipe("PIPE");
  Pipe->SetGeometryFileName("beampipe_201309.root");
  fRun->AddModule(Pipe);
  //-------------------------  STT       -----------------
  FairDetector *Stt = new PndStt("STT", kTRUE);
  Stt->SetGeometryFileName("straws_skewed_blocks_35cm_pipe.geo");
  fRun->AddModule(Stt);
  //-------------------------  MVD       -----------------
  FairDetector *Mvd = new PndMvdDetector("MVD", kTRUE);
  Mvd->SetGeometryFileName("Mvd-2.1_FullVersion.root");
  fRun->AddModule(Mvd);
  //-------------------------  GEM       -----------------
  FairDetector *Gem = new PndGemDetector("GEM", kTRUE);
  Gem->SetGeometryFileName("gem_3Stations_Tube.root");
  fRun->AddModule(Gem);
  //-------------------------  EMC       -----------------
  PndEmc *Emc = new PndEmc("EMC", kTRUE);
  Emc->SetGeometryVersion(1);
  Emc->SetStorageOfData(kFALSE);
  fRun->AddModule(Emc);
  //-------------------------  SCITIL    -----------------
  FairDetector *SciT = new PndSciT("SCIT", kTRUE);
  SciT->SetGeometryFileName("barrel-SciTil_07022013.root");
  fRun->AddModule(SciT);
  //-------------------------  DRC       -----------------
  PndDrc *Drc = new PndDrc("DIRC", kTRUE);
  Drc->SetGeometryFileName("dirc_l0_p0_updated.root");
  Drc->SetRunCherenkov(kFALSE);
  fRun->AddModule(Drc);
  //-------------------------  DISC      -----------------
  PndDsk *Dsk = new PndDsk("DSK", kTRUE);
  Dsk->SetStoreCerenkovs(kFALSE);
  Dsk->SetStoreTrackPoints(kFALSE);
  fRun->AddModule(Dsk);
  //-------------------------  MDT       -----------------
  PndMdt *Muo = new PndMdt("MDT", kTRUE);
  Muo->SetBarrel("fast");
  Muo->SetEndcap("fast");
  Muo->SetMuonFilter("fast");
  Muo->SetForward("fast");
  Muo->SetMdtMagnet(kTRUE);
  Muo->SetMdtCoil(kTRUE);
  Muo->SetMdtMFIron(kTRUE);
  fRun->AddModule(Muo);
  //-------------------------  FTS       -----------------
  FairDetector *Fts = new PndFts("FTS", kTRUE);
  Fts->SetGeometryFileName("fts.geo");
  fRun->AddModule(Fts);
  //-------------------------  FTOF      -----------------
  FairDetector *FTof = new PndFtof("FTOF", kTRUE);
  FTof->SetGeometryFileName("ftofwall.root");
  fRun->AddModule(FTof);
  //-------------------------  RICH       ----------------
  FairDetector *Rich = new PndRich("RICH", kFALSE);
  Rich->SetGeometryFileName("rich_v2_shift.geo");
  fRun->AddModule(Rich);

  // Create and Set Event Generator
  //-------------------------------
  FairPrimaryGenerator *primGen = new FairPrimaryGenerator();
  fRun->SetGenerator(primGen);

  if (UseDpm) {
    PndDpmDirect *Dpm = new PndDpmDirect(mom, 1);
    primGen->AddGenerator(Dpm);
  }
  if (UseFtf) {
    TString macfile = gSystem->Getenv("VMCWORKDIR");
    macfile += "/pgenerators/FtfEvtGen/PbarP.mac";
    PndFtfDirect *Ftf = new PndFtfDirect(macfile.Data());
    primGen->AddGenerator(Ftf);
  }
  if (UseEvtGenDirect) {
    TString EvtInput = gSystem->Getenv("VMCWORKDIR");
    EvtInput += "/macro/run/psi2s_Jpsi2pi_Jpsi_mumu.dec";
    PndEvtGenDirect *EvtGen = new PndEvtGenDirect("pbarpSystem", EvtInput.Data(), mom);
    EvtGen->SetStoreTree(kTRUE);
    primGen->AddGenerator(EvtGen);
  }

  //---------------------Create and Set the Field(s)----------
  PndMultiField *fField = new PndMultiField("AUTO");
  fRun->SetField(fField);

  // EMC Hit producer
  //-------------------------------
  PndEmcHitProducer *emcHitProd = new PndEmcHitProducer();
  fRun->AddTask(emcHitProd);

  //-------------------------  Initialize the RUN  -----------------
  fRun->Init();
  //-------------------------  Run the Simulation  -----------------
  fRun->Run(nEvents);
  //-------------------------  Save the parameters -----------------
  rtdb->saveOutput();
  //------------------------Print some info and exit----------------
  timer.Stop();
  Double_t rtime = timer.RealTime();
  Double_t ctime = timer.CpuTime();
  printf("RealTime=%f seconds, CpuTime=%f seconds\n", rtime, ctime);

  cout << " Test passed" << endl;
  cout << " All ok " << endl;

  // exit(0);
}

int reco()
{
  // Load basic libraries\par
  gROOT->LoadMacro("$VMCWORKDIR/gconfig/rootlogon.C");
  rootlogon();

  Int_t iVerbose = 3;
  Int_t nEvents = 0;

  // -----   Timer   --------------------------------------------------------
  TStopwatch timer;
  timer.Start();

  TString directory = gSystem->Getenv("VMCWORKDIR");
  TString simFile = "test_G4.root";
  TString parFile = "params_G4.root";
  TString digiFile = "digi_G4.root";

  TString recoFile = "reco_G4.root";

  TString digiparFile = gSystem->Getenv("VMCWORKDIR");
  digiparFile += "/macro/params/lumi.digi.par";

  FairRunAna *fRun = new FairRunAna();
  fRun->SetInputFile(digiFile);
  fRun->SetOutputFile(recoFile);

  FairRuntimeDb *rtdb = fRun->GetRuntimeDb();

  FairParRootFileIo *parInput1 = new FairParRootFileIo(kTRUE);
  parInput1->open(parFile.Data(), "UPDATE");
  rtdb->setFirstInput(parInput1);

  FairParAsciiFileIo *parInput2 = new FairParAsciiFileIo();
  parInput2->open(digiparFile.Data(), "in");
  rtdb->setSecondInput(parInput2);

  //	fRun->SetGeomFile(geofile);
  //   fRun->LoadGeometry();

  /** Run Clusterization **/
  Double_t charge_cut = 7000000;

  PndLumiClusterTask *lumiCluster = new PndLumiClusterTask(charge_cut, 0, 1, 0, iVerbose);
  fRun->AddTask(lumiCluster);

  // Initialize and run\par
  fRun->Init();
  fRun->Run(0, nEvents);

  rtdb->saveOutput();
  rtdb->print();

  timer.Stop();
  Double_t rtime = timer.RealTime();
  Double_t ctime = timer.CpuTime();
  cout << endl << endl;
  cout << "Macro finished succesfully." << endl;
  cout << "Real time " << rtime << " s, CPU time " << ctime << " s" << endl;
  cout << endl;
  return 0;
}
